yoy_nf_rating = [round(r['avg_rating'], 2) for r in d['yearly_non_fiction']]

# Chart 3: Price-Rating scatter data (sample for performance)
scatter_points = [(p['Price'], p['User Rating'], p['Genre']) for p in d['scatter']]

# Chart 4: Price segment distribution
seg_labels = [s['PriceSegment'] for s in d['segments']]
